<?php $labels=['passing'=>'Passe','dribbling'=>'Dribble','shooting'=>'Tir','first_touch'=>'Contrôle','tackling'=>'Tacle','vision'=>'Vision','composure'=>'Sang-froid','work_rate'=>'Travail','positioning'=>'Placement','pace'=>'Vitesse','stamina'=>'Endurance','strength'=>'Force','jumping'=>'Détente','reflexes'=>'Réflexes','handling'=>'Prises de balle','aerial_reach'=>'Jeu aérien','command_of_area'=>'Surface','kicking'=>'Dégagements']; ?>
<div class="player-hero"><div class="player-hero__identity"><span class="avatar avatar--xl"><?= e(substr($player['first_name'],0,1).substr($player['last_name'],0,1)) ?></span><div><span class="eyebrow"><?= e($player['club_name'] ?? 'Joueur libre') ?></span><h1><?= e($player['first_name'].' '.$player['last_name']) ?></h1><p><span class="position-badge"><?= e($player['primary_position']) ?></span> · <?= player_age($player['birth_date'],$save['current_date']) ?> ans · <?= e($player['nationality']) ?> · Pied <?= e($player['preferred_foot']) ?></p></div></div><div class="player-hero__ratings"><div><strong><?= (int)$player['overall_rating'] ?></strong><span>OVR</span></div><div><strong><?= (int)$player['potential'] ?></strong><span>POT</span></div></div></div>
<div class="player-grid"><section class="panel"><div class="panel__header"><h2>Profil des attributs</h2></div><div class="panel__body radar-wrap"><canvas id="player-radar" width="420" height="360" data-radar="<?= e(json_encode($radar, JSON_HEX_APOS|JSON_HEX_QUOT)) ?>"></canvas></div></section>
<section class="panel"><div class="panel__header"><h2>État et contrat</h2></div><div class="panel__body"><dl class="facts"><div><dt>Valeur marchande</dt><dd><?= format_money($player['market_value']) ?></dd></div><div><dt>Salaire / semaine</dt><dd><?= format_money($player['contract_salary'] ?? 0) ?></dd></div><div><dt>Fin de contrat</dt><dd><?= format_date($player['contract_ends']) ?></dd></div><div><dt>Rôle</dt><dd><?= e($player['squad_role'] ?? 'Libre') ?></dd></div><div><dt>Taille / poids</dt><dd><?= (int)$player['height_cm'] ?> cm · <?= (int)$player['weight_kg'] ?> kg</dd></div></dl><div class="status-bars"><label>Forme <b><?= (int)$player['form'] ?>%</b><div class="progress"><span style="width:<?= (int)$player['form'] ?>%"></span></div></label><label>Moral <b><?= (int)$player['morale'] ?>%</b><div class="progress"><span style="width:<?= (int)$player['morale'] ?>%"></span></div></label><label>Fatigue <b><?= (int)$player['fatigue'] ?>%</b><div class="progress progress--danger"><span style="width:<?= (int)$player['fatigue'] ?>%"></span></div></label></div><?php if ($player['injury_type']): ?><div class="alert alert--danger"><strong><?= e($player['injury_type']) ?></strong><br>Retour estimé : <?= format_date($player['injury_until']) ?></div><?php endif; ?></div></section>
<section class="panel panel--wide"><div class="panel__header"><h2>Attributs détaillés</h2></div><div class="panel__body attribute-grid"><?php foreach ($attributes as $attribute): ?><div><span><?= e($labels[$attribute]) ?></span><b class="rating rating--<?= $player[$attribute]>=75?'high':($player[$attribute]>=60?'mid':'low') ?>"><?= (int)$player[$attribute] ?></b><div class="mini-bar"><span style="width:<?= (int)$player[$attribute] ?>%"></span></div></div><?php endforeach; ?></div></section>
<section class="panel"><div class="panel__header"><h2>Progression récente</h2></div><div class="panel__body"><?php if (!$progress): ?><p class="muted">Aucun rapport pour le moment.</p><?php endif; ?><div class="timeline"><?php foreach ($progress as $entry): ?><div><time><?= format_date($entry['week_start'],'d/m/Y') ?></time><span><?= e($entry['attribute'] ? $labels[$entry['attribute']] ?? $entry['attribute'] : 'Récupération') ?><?php if ($entry['attribute'] && $entry['new_value'] !== null): ?> : <strong><?= (int)$entry['previous_value'] ?> → <?= (int)$entry['new_value'] ?></strong><?php endif; ?></span></div><?php endforeach; ?></div></div></section>
<section class="panel"><div class="panel__header"><h2>Historique des transferts</h2></div><div class="panel__body"><?php if (!$history): ?><p class="muted">Aucun transfert enregistré.</p><?php endif; ?><div class="timeline"><?php foreach ($history as $transfer): ?><div><time><?= format_date($transfer['transfer_date'],'d/m/Y') ?></time><span><?= e($transfer['from_name'] ?? 'Libre') ?> → <?= e($transfer['to_name'] ?? 'Libre') ?> · <strong><?= format_money($transfer['fee']) ?></strong></span></div><?php endforeach; ?></div></div></section></div>
